@SuppressWarnings("null")
private Supplier<ConversionService> getConversionService() {
    return () -> {
        RequestAttributes attributes = RequestContextHolder.getRequestAttributes();

        // Check if attributes is an instance of ServletRequestAttributes and if the attributes are not null
        if (!(attributes instanceof ServletRequestAttributes)) {
            return FALLBACK_CONVERSION_SERVICE;
        }

        // Cast and get the request, then check if request is not null before proceeding
        ServletRequestAttributes servletRequestAttributes = (ServletRequestAttributes) attributes;
        HttpServletRequest request = servletRequestAttributes.getRequest();

        if (request == null) {
            return FALLBACK_CONVERSION_SERVICE;
        }

        ServletContext servletContext = request.getServletContext();
        WebApplicationContext context = WebApplicationContextUtils.getWebApplicationContext(servletContext);

        return context == null || !context.containsBean("mvcConversionService")
                ? FALLBACK_CONVERSION_SERVICE
                : context.getBean("mvcConversionService", ConversionService.class);
    };
}

